function lampsOn(n: number): number {
  const on = new Uint8Array(n + 1);
  for (let k = 1; k <= n; k++) for (let i = k; i <= n; i += k) on[i] ^= 1;
  let count = 0;
  for (let i = 1; i <= n; i++) count += on[i];
  return count;
}

